<?php
use DigiForge\PortalAccess\{Authentication,Feature,Session,Store};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class PortalAuthenticationTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();}
 protected function tearDown():void{global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function ready():void{self::assertTrue(class_exists(Authentication::class),'Portal authentication is not implemented');}
 public function testDedicatedLoginAndAccountNavigationUseWordPressRecoveryAndNonceLogout():void{$this->ready();$html=Authentication::render();self::assertStringContainsString('DigiForge',$html);self::assertStringContainsString('lostpassword',$html);self::assertStringContainsString('_wpnonce',$html);PortalAccessFixture::owner();$bar=Feature::accountBar();self::assertStringContainsString('action=logout',$bar);self::assertStringContainsString('_wpnonce',$bar);}
 public function testLoginRejectsNonceAndExternalRedirect():void{$this->ready();self::assertWPError(Authentication::process(['login'=>'x','password'=>'x','_wpnonce'=>'wrong']));self::assertSame(home_url('/'),Authentication::safeReturn('https://attacker.invalid/'));self::assertSame(home_url('/'),Authentication::safeReturn('//attacker.invalid/'));}
 public function testExistingWordPressAccountCanAuthenticateWithoutCreatingOwner():void{$this->ready();$id=self::factory()->user->create(['user_login'=>'portal_auth_fixture','user_pass'=>'syntheticFixturePass123!','role'=>'subscriber']);wp_set_current_user(0);$r=Authentication::process(['login'=>'portal_auth_fixture','password'=>'syntheticFixturePass123!','challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)]);self::assertNotWPError($r);self::assertSame($id,$r['actor_id']);self::assertNull(Store::read($id));self::assertWPError(\DigiForge\PortalAccess\Owner::require('personalized_pod'));}
 public function testLoginIsBoundedAndDoesNotEnumerateAccounts():void{$this->ready();wp_set_current_user(0);$p=['login'=>'absent_fixture','password'=>'bad','challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)];$message=null;for($i=0;$i<6;$i++){$r=Authentication::process($p);self::assertWPError($r);$message??=$r->get_error_message();self::assertSame($message,$r->get_error_message());}self::assertSame('digiforge_portal_login_throttled',$r->get_error_code());}
 public function testSharedGuestNonceWithoutBrowserChallengeDoesNotReserveOrAttemptLogin():void{$this->ready();wp_set_current_user(0);global $wpdb;$before=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE %s",$wpdb->esc_like('digiforge_portal_rate_').'%'));Authentication::process(['login'=>'missing_challenge_fixture','password'=>'bad','_wpnonce'=>wp_create_nonce(Authentication::ACTION)]);$after=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE %s",$wpdb->esc_like('digiforge_portal_rate_').'%'));self::assertSame($before,$after);}

 public function testPendingInviteCanLoginToAcceptanceWithoutReceivingPortalSession():void{$this->ready();PortalAccessFixture::enroll();$id=self::factory()->user->create(['user_login'=>'pending_login_fixture','user_pass'=>'syntheticPendingPass123!','role'=>'administrator']);$invite=\DigiForge\PortalAccess\Invitations::create($id,'Viewer','personalized_pod',['research'],time()+600,wp_generate_uuid4());self::assertNotWPError($invite);wp_set_current_user(0);$_COOKIE=[];$url=add_query_arg('df_view','invitation',home_url('/'));$r=Authentication::process(['login'=>'pending_login_fixture','password'=>'syntheticPendingPass123!','challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION),'return_to'=>$url]);self::assertNotWPError($r);self::assertSame($url,$r['return_to']);self::assertFalse(Session::valid(Store::read($id)));self::assertNotWPError(\DigiForge\PortalAccess\Invitations::accept($invite['token'],wp_generate_uuid4()));self::assertTrue(Session::valid(Store::read($id)));}

}
